import{_ as a,o as n,c as i,a as _}from"./app.DkoUFz-u.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"backend/messaging/kafka/streams.md","filePath":"backend/messaging/kafka/streams.md"}'),p={name:"backend/messaging/kafka/streams.md"};function t(l,s,h,e,o,c){return n(),i("div",null,[...s[0]||(s[0]=[_(`<p>理解Kafka的流处理能力对于构建实时数据管道和应用至关重要。下面这份学习笔记整理了Kafka流处理的核心概念、架构、API使用及最佳实践，希望能帮助你系统地掌握这一技术。</p><h3 id="✨-kafka流处理核心概念" tabindex="-1">✨ Kafka流处理核心概念 <a class="header-anchor" href="#✨-kafka流处理核心概念" aria-label="Permalink to &quot;✨ Kafka流处理核心概念&quot;">​</a></h3><p>要理解Kafka的流处理，首先需要掌握一些基础概念：</p><ul><li><strong>事件流</strong>：Kafka流处理的核心是处理<strong>无界的数据集</strong>，这些数据代表业务中发生的一系列事件。事件流具有三个关键特性：<strong>有序性</strong>（事件有明确的先后顺序）、<strong>不可变性</strong>（已发生的事件无法改变）和<strong>可重放性</strong>（流可以被多次消费，用于纠错、审计或新分析）。</li><li><strong>流处理范式</strong>：流处理填补了<strong>请求-响应</strong>（低延迟，通常毫秒级）和<strong>批处理</strong>（高延迟，通常数小时或数天）之间的空白。它允许应用程序<strong>连续地</strong>处理和响应数据，适用于大多数不需要毫秒级响应，但也不能容忍天级别延迟的业务场景。</li></ul><h3 id="🏗️-kafka-streams-架构剖析" tabindex="-1">🏗️ Kafka Streams 架构剖析 <a class="header-anchor" href="#🏗️-kafka-streams-架构剖析" aria-label="Permalink to &quot;🏗️ Kafka Streams 架构剖析&quot;">​</a></h3><p>Kafka Streams是一个用于构建流处理程序的Java客户端库，它<strong>无需额外的流处理集群</strong>，仅依赖于Kafka本身。</p><ol><li><p><strong>核心API</strong>：</p><ul><li><strong>KStream</strong>：代表一系列连续的、无界的键值对数据。它用于处理数据流中的每一个独立事件。</li><li><strong>KTable</strong>：代表流在某个时间点的<strong>可变状态快照</strong>，通常由流聚合操作产生。可以将KStream视为数据库的<strong>重做日志</strong>，而KTable则是<strong>当前的数据表状态</strong>。</li></ul></li><li><p><strong>拓扑构建</strong>：Kafka Streams应用被构建成一个<strong>处理器拓扑</strong>（一个由流处理节点构成的有向图），定义了数据从输入到输出的完整处理逻辑。</p></li><li><p><strong>容错与状态</strong>：通过<strong>状态存储</strong>和<strong>变更日志主题</strong>实现容错。当应用失败时，可以从Kafka的变更日志主题中恢复状态，确保处理的正确性。</p></li></ol><h3 id="🛠️-流处理api与实战" tabindex="-1">🛠️ 流处理API与实战 <a class="header-anchor" href="#🛠️-流处理api与实战" aria-label="Permalink to &quot;🛠️ 流处理API与实战&quot;">​</a></h3><p>Kafka Streams提供了丰富的API来处理数据。</p><ol><li><p><strong>数据清洗与转换</strong> 这是最常见的操作，用于过滤无效数据或进行格式标准化。</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">StreamsBuilder builder </span><span class="__shiki_1itgoe">=</span><span class="__shiki_1itgoe"> new</span><span class="__shiki_1t8gfj"> StreamsBuilder</span><span class="__shiki_140thh">();</span></span>
<span class="line"><span class="__shiki_21nrsd">// 从输入主题创建KStream</span></span>
<span class="line"><span class="__shiki_140thh">KStream&lt;</span><span class="__shiki_1itgoe">String</span><span class="__shiki_140thh">, </span><span class="__shiki_1itgoe">String</span><span class="__shiki_140thh">&gt; source </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> builder.</span><span class="__shiki_1t8gfj">stream</span><span class="__shiki_140thh">(</span><span class="__shiki_mdbnqw">&quot;input-topic&quot;</span><span class="__shiki_140thh">);</span></span>
<span class="line"><span class="__shiki_21nrsd">// 过滤空值并转换</span></span>
<span class="line"><span class="__shiki_140thh">KStream&lt;</span><span class="__shiki_1itgoe">String</span><span class="__shiki_140thh">, </span><span class="__shiki_1itgoe">String</span><span class="__shiki_140thh">&gt; cleaned </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> source.</span><span class="__shiki_1t8gfj">filter</span><span class="__shiki_140thh">((key, value) </span><span class="__shiki_1itgoe">-&gt;</span><span class="__shiki_140thh"> value </span><span class="__shiki_1itgoe">!=</span><span class="__shiki_dzsirb"> null</span><span class="__shiki_1itgoe"> &amp;&amp;</span><span class="__shiki_1itgoe"> !</span><span class="__shiki_140thh">value.</span><span class="__shiki_1t8gfj">isEmpty</span><span class="__shiki_140thh">())</span></span>
<span class="line"><span class="__shiki_140thh">                                      .</span><span class="__shiki_1t8gfj">mapValues</span><span class="__shiki_140thh">(value </span><span class="__shiki_1itgoe">-&gt;</span><span class="__shiki_140thh"> value.</span><span class="__shiki_1t8gfj">toLowerCase</span><span class="__shiki_140thh">());</span></span>
<span class="line"><span class="__shiki_21nrsd">// 输出到新主题</span></span>
<span class="line"><span class="__shiki_140thh">cleaned.</span><span class="__shiki_1t8gfj">to</span><span class="__shiki_140thh">(</span><span class="__shiki_mdbnqw">&quot;cleaned-data&quot;</span><span class="__shiki_140thh">);</span></span></code></pre></div></li><li><p><strong>聚合计算</strong> 对数据按Key进行分组并汇总，例如计算单词出现次数或用户行为次数。</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">// 按键分组</span></span>
<span class="line"><span class="__shiki_140thh">KGroupedStream&lt;</span><span class="__shiki_1itgoe">String</span><span class="__shiki_140thh">, </span><span class="__shiki_1itgoe">String</span><span class="__shiki_140thh">&gt; grouped </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> source.</span><span class="__shiki_1t8gfj">groupByKey</span><span class="__shiki_140thh">();</span></span>
<span class="line"><span class="__shiki_21nrsd">// 计数</span></span>
<span class="line"><span class="__shiki_140thh">KTable&lt;</span><span class="__shiki_1itgoe">String</span><span class="__shiki_140thh">, </span><span class="__shiki_1itgoe">Long</span><span class="__shiki_140thh">&gt; counts </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> grouped.</span><span class="__shiki_1t8gfj">count</span><span class="__shiki_140thh">(Materialized.</span><span class="__shiki_1t8gfj">as</span><span class="__shiki_140thh">(</span><span class="__shiki_mdbnqw">&quot;counts-store&quot;</span><span class="__shiki_140thh">));</span></span>
<span class="line"><span class="__shiki_21nrsd">// 将结果流式输出</span></span>
<span class="line"><span class="__shiki_140thh">counts.</span><span class="__shiki_1t8gfj">toStream</span><span class="__shiki_140thh">().</span><span class="__shiki_1t8gfj">to</span><span class="__shiki_140thh">(</span><span class="__shiki_mdbnqw">&quot;aggregated-data&quot;</span><span class="__shiki_140thh">, Produced.</span><span class="__shiki_1t8gfj">with</span><span class="__shiki_140thh">(Serdes.</span><span class="__shiki_1t8gfj">String</span><span class="__shiki_140thh">(), Serdes.</span><span class="__shiki_1t8gfj">Long</span><span class="__shiki_140thh">()));</span></span></code></pre></div></li><li><p><strong>窗口操作</strong> 用于对特定时间段内的数据进行计算，例如每5分钟的页面访问量。</p><ul><li><strong>滚动窗口</strong>：固定的、不重叠的时间窗口。</li><li><strong>滑动窗口</strong>：窗口之间存在重叠。</li></ul><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">// 定义一个5分钟的滚动窗口</span></span>
<span class="line"><span class="__shiki_140thh">TimeWindows timeWindows </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> TimeWindows.</span><span class="__shiki_1t8gfj">of</span><span class="__shiki_140thh">(Duration.</span><span class="__shiki_1t8gfj">ofMinutes</span><span class="__shiki_140thh">(</span><span class="__shiki_dzsirb">5</span><span class="__shiki_140thh">));</span></span>
<span class="line"><span class="__shiki_140thh">KGroupedStream&lt;</span><span class="__shiki_1itgoe">String</span><span class="__shiki_140thh">, </span><span class="__shiki_1itgoe">String</span><span class="__shiki_140thh">&gt; grouped </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> source.</span><span class="__shiki_1t8gfj">groupByKey</span><span class="__shiki_140thh">();</span></span>
<span class="line"><span class="__shiki_21nrsd">// 应用窗口并进行计数</span></span>
<span class="line"><span class="__shiki_140thh">KTable&lt;Windowed&lt;</span><span class="__shiki_1itgoe">String</span><span class="__shiki_140thh">&gt;, </span><span class="__shiki_1itgoe">Long</span><span class="__shiki_140thh">&gt; windowCounts </span><span class="__shiki_1itgoe">=</span><span class="__shiki_140thh"> grouped.</span><span class="__shiki_1t8gfj">windowedBy</span><span class="__shiki_140thh">(timeWindows)</span></span>
<span class="line"><span class="__shiki_140thh">                                                    .</span><span class="__shiki_1t8gfj">count</span><span class="__shiki_140thh">(Materialized.</span><span class="__shiki_1t8gfj">as</span><span class="__shiki_140thh">(</span><span class="__shiki_mdbnqw">&quot;window-counts-store&quot;</span><span class="__shiki_140thh">));</span></span></code></pre></div></li></ol><h3 id="💡-流处理设计模式" tabindex="-1">💡 流处理设计模式 <a class="header-anchor" href="#💡-流处理设计模式" aria-label="Permalink to &quot;💡 流处理设计模式&quot;">​</a></h3><p>在实际应用中，有几种常见的流处理设计模式：</p><ul><li><strong>单事件处理</strong>：最简单的方式，独立处理流中的每一个事件。</li><li><strong>使用本地状态</strong>：在处理过程中维护一个可查询的本地状态存储，用于存储聚合结果或中间数据。</li><li><strong>流表连接</strong>：将一个动态的事件流（KStream）与一个动态的表（KTable）进行连接，用表中的最新状态来丰富流中的数据。</li><li><strong>流连接</strong>：将两个具有相同Key的事件流进行连接，基于一个时间窗口来组合相关的事件。</li></ul><h3 id="📊-扩展、监控与优化" tabindex="-1">📊 扩展、监控与优化 <a class="header-anchor" href="#📊-扩展、监控与优化" aria-label="Permalink to &quot;📊 扩展、监控与优化&quot;">​</a></h3><ol><li><p><strong>扩展拓扑</strong>：Kafka Streams应用的并行度由<strong>输入主题的分区数</strong>决定。每个分区可以被一个应用实例独立消费，因此增加分区数和应用实例数可以实现水平扩展。</p></li><li><p><strong>监控与测试</strong>：</p><ul><li><strong>监控</strong>：可以利用Kafka自带的监控指标（如消费延迟）进行监控，同时Kafka Streams也集成了JMX，可以暴露丰富的应用指标。</li><li><strong>测试</strong>：Kafka Streams提供了<code>TopologyTestDriver</code>工具，可以在不依赖Kafka集群的情况下对处理拓扑进行单元测试。</li></ul></li><li><p><strong>性能优化</strong>：</p><ul><li><strong>生产者端</strong>：可以调整<code>linger.ms</code>参数进行适当的批量发送，并启用压缩（如<code>compression.type=lz4</code>）。</li><li><strong>Broker端</strong>：分离数据目录与日志目录，并调整I/O线程数。</li><li><strong>分区设计</strong>：合理设置Topic的分区数量，以平衡并行度和系统开销。</li></ul></li></ol><h3 id="🚀-ksql-流处理的sql方案" tabindex="-1">🚀 KSQL：流处理的SQL方案 <a class="header-anchor" href="#🚀-ksql-流处理的sql方案" aria-label="Permalink to &quot;🚀 KSQL：流处理的SQL方案&quot;">​</a></h3><p>除了编程式的Kafka Streams API，还可以使用<strong>KSQL</strong>，这是一种用于Kafka流处理的SQL引擎。它允许使用类似SQL的语法来定义流处理任务，降低了开发门槛。</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_21nrsd">-- 定义一个数据流</span></span>
<span class="line"><span class="__shiki_1itgoe">CREATE</span><span class="__shiki_140thh"> STREAM pageviews (viewtime </span><span class="__shiki_1itgoe">BIGINT</span><span class="__shiki_140thh">, userid </span><span class="__shiki_1itgoe">VARCHAR</span><span class="__shiki_140thh">, pageid </span><span class="__shiki_1itgoe">VARCHAR</span><span class="__shiki_140thh">) </span></span>
<span class="line"><span class="__shiki_1itgoe">    WITH</span><span class="__shiki_140thh"> (kafka_topic</span><span class="__shiki_1itgoe">=</span><span class="__shiki_mdbnqw">&#39;pageviews&#39;</span><span class="__shiki_140thh">, value_format</span><span class="__shiki_1itgoe">=</span><span class="__shiki_mdbnqw">&#39;JSON&#39;</span><span class="__shiki_140thh">);</span></span>
<span class="line"><span class="__shiki_21nrsd">-- 创建一个表，计算每分钟的用户页面访问量</span></span>
<span class="line"><span class="__shiki_1itgoe">CREATE</span><span class="__shiki_1itgoe"> TABLE</span><span class="__shiki_1t8gfj"> user_pageviews</span><span class="__shiki_1itgoe"> AS</span><span class="__shiki_140thh"> </span></span>
<span class="line"><span class="__shiki_1itgoe">    SELECT</span><span class="__shiki_140thh"> userid, </span><span class="__shiki_dzsirb">COUNT</span><span class="__shiki_140thh">(</span><span class="__shiki_1itgoe">*</span><span class="__shiki_140thh">) </span><span class="__shiki_1itgoe">AS</span><span class="__shiki_140thh"> num_views </span></span>
<span class="line"><span class="__shiki_1itgoe">    FROM</span><span class="__shiki_140thh"> pageviews </span></span>
<span class="line"><span class="__shiki_1itgoe">    WINDOW</span><span class="__shiki_140thh"> TUMBLING (</span><span class="__shiki_1itgoe">SIZE</span><span class="__shiki_dzsirb"> 1</span><span class="__shiki_1itgoe"> MINUTE</span><span class="__shiki_140thh">) </span></span>
<span class="line"><span class="__shiki_1itgoe">    GROUP BY</span><span class="__shiki_140thh"> userid;</span></span></code></pre></div><h3 id="💎-核心优势与典型用例" tabindex="-1">💎 核心优势与典型用例 <a class="header-anchor" href="#💎-核心优势与典型用例" aria-label="Permalink to &quot;💎 核心优势与典型用例&quot;">​</a></h3><p>Kafka流处理的核心优势在于其<strong>高吞吐、低延迟</strong>的架构设计（如利用页缓存和零拷贝技术），以及<strong>水平扩展的弹性能力</strong>和<strong>强大的持久化存储与容错机制</strong>。</p><p>其典型的应用场景包括：</p><ul><li><strong>实时数据分析与监控</strong></li><li><strong>数据清洗与转换</strong></li><li><strong>复杂事件处理</strong></li><li><strong>物联网设备数据的实时处理</strong></li></ul><p>希望这份笔记能帮助你构建起Kafka流处理的知识体系！如果你对某个特定方面，比如窗口操作的更详细类型或者状态管理的深入原理感兴趣，我很乐意提供进一步的探讨。</p>`,23)])])}const k=a(p,[["render",t]]);export{g as __pageData,k as default};
